INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-056', 'SW', 'P3', 'OPEN', NULL, NULL, 'scripts/db.py''s _require_verbatim digit-check (add-extraction''s claimed_value verification, ~line 6579) was widened 2026- to accept CJK numerals alongside Arabic digits, but has no path for LATIN-SCRIPT SPELLED-OUT CARDINAL NUMBERS -- e.g. Finnish ''viisi prosenttia''/''kahdeksan prosenttia'' (five/eight percent), which is how Finland''s Decree 241/2017 states its ramp-gradient figures throughout (no digit form appears anywhere in the statute text). A claimed_value written in digit form (''5%'') is refused because no digit character occurs in the verified claim_text; --verbatim-exempt cannot rescue it either, because exemption is refused whenever the claim_text DOES verify against a persisted artefact (it does here). Net effect: a genuinely verbatim-verified numerical claim from a language that spells cardinals as words has NO path to carry a digit-form claimed_value at all. Worked around in batch 22 (REF-01017, Finland, extraction on parameter 3) by setting claimed_value to the source''s own spelled-out form (''viisi prosenttia'') and giving the digit-equivalent only as an editorial gloss in --claimed-unit/--notes, explicitly marked as non-verbatim. Fix belongs in a tooling-only PR (rule 10): extend the digit-check with a small per-language cardinal-number lexicon (or a number-parsing library) analogous to the existing _CJK_DIGITS/_CJK_UNITS tables, or provide an explicit escape that documents a spelled-out-to-digit mapping without requiring the exemption path. R5 (non-English work is academic, not lesser) applies here exactly as it did for the CJK fix this function''s own comment already describes.', '2026-09-28 20:18', 'session_2026-09-28-research-batch-22-selection', '2026-09-28 20:18', 'session_2026-09-28-research-batch-22-selection', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-057', 'SW', 'P3', 'CLOSED-DUPLICATE', NULL, NULL, 'R3 (research_batch_dod.py) checks evidence_sources.article_number/pages for a clause/section/page locator on every tier>=4 regulatory source, but this batch''s 6 new admissions (REF-01012 through REF-01017) omitted --pages at add-source time (operator error -- the flag exists and other tier>=4 rows in the corpus do carry it). Discovered when trying to backfill: amend-source blanket-refuses ''pages''/''article_number'' as bibliographic fields not amendable by hand, directing to correct-source -- but correct-source can ONLY populate a bibliographic field from a structured citation-service payload already logged via retrieval_log (Crossref/PubMed-shaped JSON), which does not exist and cannot exist for a non-DOI government regulation/standard. Net effect: once a regulatory source is added without --pages, there is NO sanctioned path to add one afterward, even though the real locator is known, verified, and already recorded precisely at the extraction level (source_value_extractions.source_section/loc_section/loc_paragraph/loc_clause) for all 6 rows. R3''s letter is unmet on these 6 but its intent (a real, verified clause locator exists) is satisfied one table over. Recorded as a reasoned waiver on R3 for this batch''s PR rather than hand-editing evidence_sources. Fix belongs in a tooling-only PR (rule 10): either add a sanctioned amend-source path for pages/article_number gated on evidence_type IN (''code'',''standard'') (i.e. non-DOI regulatory sources, where there is no citation-service payload to defer to), or have R3 additionally accept a populated source_section/loc_section on the source''s own extractions as satisfying the clause-citation intent, rather than requiring a second, redundant copy of the same locator on evidence_sources -- which risks becoming a rule-5 violation in the other direction if a source later carries multiple extractions with DIFFERENT clause numbers.', '2026-09-28 20:24', 'session_2026-09-28-research-batch-22-selection', '2026-09-28 20:53', 'session_2026-09-28-research-batch-22-selection', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "research_code_leads" ("lead_id", "jurisdiction", "standard_name", "clause", "status", "recovered_from", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (94, 'ISO', 'ISO 21542:2011 (published, distinct from the 2007 CD draft admitted as REF-01014)', 'Ramp max-rise/max-slope/max-landing-interval schedule (graduated 1:20 to 1:8, kerb-ramps-only below 1:12), cited but not reproduced verbatim, in UNICEF Accessibility Technical Cards (2022) p.14, captioned ''(Source: ISO 2011)''', 'REFERENCE-ONLY', 'UNICEF Accessibility Technical Cards (2022), tertiary citation only -- not independently retrieved', 'Surfaced during batch-22 UN search (exec_id 113, accessible-circulation-geometry parameter 3). The published 2011 standard appears to carry a more granular graduated schedule than the 2007 CD draft text extracted for REF-01014; worth retrieving primarily if a non-paywalled copy can be found, to confirm/supersede REF-01014''s tier-4 extraction with the actual published clause numbers.', '2026-09-28 20:07', 'session_2026-09-28-research-batch-22-selection', NULL, NULL);
INSERT INTO "research_code_leads" ("lead_id", "jurisdiction", "standard_name", "clause", "status", "recovered_from", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (95, 'INT', 'UNESCO (1990), Barrier-Free Design guidance (title unconfirmed -- cited only as ''UNESCO 1990'' throughout secondary sources)', 'Pathway gradient: not steeper than 1:20 general, max 1:12 for short distances, cited (not reproduced verbatim) in UNICEF Accessibility Technical Cards (2022) p.7, captioned ''(Source: UNESCO 1990, Centre for Accessible Environments and RIBA 2004)''', 'REFERENCE-ONLY', 'UNICEF Accessibility Technical Cards (2022), tertiary citation only -- not independently retrieved', 'Surfaced during batch-22 UN search (exec_id 113). Also cited by name (not title) for 15+ other figures across the same UNICEF document; exact publication title/publisher not yet confirmed -- ''UNESCO 1990'' is the full citation given in every instance. Low priority: pre-dates the CRPD (2006) and the values it supplies (1:20/1:12) are already independently represented via REF-01008 and others in this corpus, so this lead is for provenance completeness, not a coverage gap.', '2026-09-28 20:07', 'session_2026-09-28-research-batch-22-selection', NULL, NULL);
