INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-28-resea-REF-01012-MOB', 'REF-01012', 'MOB', 'No participants: a national statutory building regulation, not a study', NULL, 'PARTIAL', 'Per the 2026-09-25 owner ruling (facility-audit population grading does not turn on participants/auditors; grade on who is served and what was measured): the regulation''s own text grounds its minimum-width provision explicitly in wheelchair use, and its gradient/landing/handrail provisions are all MOB-serving by clear intent. The measurement is one step removed -- a legal maximum, not an observation of a disabled person negotiating a ramp -- matching REF-01006/REF-01007/REF-01009/REF-01011/REF-01010''s PARTIAL precedent for code/audit sources on this parameter.', '2026-09-28 19:49', 'session_2026-09-28-research-batch-22-selection', 'REF-01012', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-28-resea-REF-01012-MOB-2', 'REF-01012', 'MOB', 'No study population -- a statutory building code/standard asserting a design requirement, not a study of any population', NULL, 'PROXY', 'CORRECTION (independent adversarial pass, batch 22): this source''s earlier PARTIAL grade misapplied the 2026-09-25 owner ruling (references/project-standards.md, point 3), which is scoped explicitly to grading a FACILITY AUDIT''s population match (its worked example, REF-01007, is a census of facilities conducted by researchers) -- not to a statutory instrument, which measures nothing and has no ''what was measured'' for the ruling''s ACTION 3 to apply to. The earlier grade also cited a ''REF-01010 PARTIAL precedent'' that does not exist: REF-01010 carries zero population-match rows in this corpus. The actual, correctly-reasoned precedent for this source TYPE is REF-00987 (ADA), REF-00994 (IPC guide) and REF-00995 (a regional decree), all graded PROXY on the same ground: ''a standard asserts a figure, it does not study a population, so there is no population-of-study to compare against MOB.'' PROXY is the correct grade here for the same reason. The earlier PARTIAL row is left in place, not deleted (append-only); this row is the corrected grade.', '2026-09-28 20:55', 'session_2026-09-28-research-batch-22-selection', 'REF-01012', NULL);
