INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (74, 'REF-01017', 'kulkuväylä', 'FI', '241/2017, 2 S (CORRECTS observation_id=72: that row''s surface_form ''kulkuvayla'' dropped the source''s own diacritics when typed -- ä was stripped, not from the source, from this session''s own transcription)', 'Ulkotilassa sijaitsevan kulkuväylän kaltevuus saa olla enintään viisi prosenttia.', NULL, '2026-09-28 21:01', 'session_2026-09-28-research-batch-22-selection', '2026-09-28 21:01', 'session_2026-09-28-research-batch-22-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (107, 'accessible-circulation-geometry', 'NO', 'NO', NULL, 'code', NULL, 'Norway TEK17 rampe maksimal stigning tilgjengelighet rullestol', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-09-28-research-batch-22-selection', '2026-09-28 19:48', 'First result (dibk.no/regelverk/tek/3/12/iii/12-18) was the SUPERSEDED TEK10 regulation -- caught before use (page states ''TEK10 er tidligere regelverk. Det nyeste regelverket er TEK17''). The correct current TEK17 section (renumbered to 12-16, not 12-18) was in the same result set and is retrieved by a dedicated follow-up exec.', 0, 'Norway has a strong universal-design tradition (TEK17/SINTEF per jurisdiction-philosophy.md''s own selection rationale) -- expect a specific, government-published (Direktoratet for byggkvalitet) maximum ramp gradient value, likely in the 1:12-1:20 range matching the tiered-by-length pattern already seen in other jurisdictions (Uganda, Spain, France, UK) in this corpus.', 'planned', NULL, NULL, '2026-09-28 19:48', 'session_2026-09-28-research-batch-22-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (108, 'accessible-circulation-geometry', 'NO', 'NO', NULL, 'code', NULL, 'https://www.dibk.no/regelverk/byggteknisk-forskrift-tek17/12/iii/12-16', NULL, 'web', 'scoping', NULL, 1, 1, 0, 'saturated', NULL, NULL, 0, 'session_2026-09-28-research-batch-22-selection', '2026-09-28 19:48', 'Confirmed verbatim, TEK17 section 12-16(2): ''Rampe skal ha jevnt og sklisikkert dekke og stigning maksimum 1:15. For strekninger under 3,0 m kan stigningen være maksimum 1:12.'' (an even, non-slip surface, gradient max 1:15, or max 1:12 for runs under 3.0m). (1): min width 0.9m (''Kravet til minimumsbredde er gitt med bakgrunn i bruk av rullestol'' -- the minimum-width requirement is set with wheelchair use as its basis). (2) also requires a 1.5m rest landing per 1.0m of height risen. (3): handrails both sides, luminance contrast >=0.8 to walls.', 0, 'Follow-up direct retrieval of the current TEK17 section 12-16 (Rampe), the correct in-force regulation after exec 107''s first hit turned out to be the superseded TEK10 version. Expect the tiered gradient figure (1:12/1:15 pattern) confirmed verbatim.', 'planned', NULL, NULL, '2026-09-28 19:48', 'session_2026-09-28-research-batch-22-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (109, 'accessible-circulation-geometry', 'CA', 'EN', NULL, 'code', NULL, 'Canada CSA B651 National Building Code ramp maximum slope accessibility wheelchair', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-09-28-research-batch-22-selection', '2026-09-28 19:55', 'Confirmed: CSA B651 PDF (csagroup.org) returned HTTP 403 on direct fetch; the Internet Archive Wayback Machine (previously working this session for Norway/batch-21 sources) returned a proxy-level connection reset for this host specifically (''ws_closed_mid_exchange'', per /root/.ccr/README.md''s diagnosis) across multiple snapshots and URLs, including a control URL known to work earlier this session -- a session-level Wayback outage, not a CSA-specific block. Pivoted to a sub-national jurisdiction per the user''s standing guidance that provinces/states/municipalities within a bucket country are valid research targets: Ontario''s Building Code (O.Reg 163/24, s.3.8.3.4) incorporates the accessibility ramp requirement into public law directly. Declared in CLAUDE.md Traps as a standing procedure for future publisher blocks.', 0, 'Canada''s national accessibility standard (CSA B651) likely specifies a ramp gradient near the ADA-family 1:12, given historical alignment with US standards; expect the standard itself to be commercially paywalled (Canadian standards bodies typically sell full text), so a provincial building code that incorporates equivalent provisions into public law may be the more retrievable primary source.', 'planned', NULL, NULL, '2026-09-28 19:55', 'session_2026-09-28-research-batch-22-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (110, 'accessible-circulation-geometry', 'CA', 'EN', NULL, 'code', NULL, 'https://www.buildingcode.online/517.html', NULL, 'web', 'scoping', NULL, 1, 1, 0, 'saturated', NULL, NULL, 0, 'session_2026-09-28-research-batch-22-selection', '2026-09-28 19:55', 'Confirmed verbatim, OBC 3.8.3.4(1): ''Ramps located in a barrier-free path of travel shall, (a) have a minimum width of 900 mm between handrails, (b) have a maximum gradient of 1 in 12, ...''. NOTE: this text is dated to the 2012/2017 edition per the page''s own plain-language note; a second, independent search (not this exec) confirmed the 2024 edition (O.Reg 163/24) states the SAME 1:12 gradient with an updated minimum width (1000mm, not 900mm) -- width not extracted here (out of this parameter''s scope), gradient value unchanged across editions. DISTINCT FROM THE GENERAL (non-accessibility) ramp-slope clause OBC 3.4.6.7, which sets occupancy-dependent slopes (1:6 to 1:10) for non-barrier-free ramps -- not this parameter; not extracted.', 0, 'Follow-up direct retrieval of the Ontario Building Code''s barrier-free ramp provision (s.3.8.3.4), found via exec 109''s pivot to a provincial source. Expect a 1:12 max gradient matching the ADA-family pattern; the page is a non-governmental mirror (self-disclosed), so also check for currency against the 2024 edition (O.Reg 163/24) before treating the value as current.', 'planned', NULL, NULL, '2026-09-28 19:55', 'session_2026-09-28-research-batch-22-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (111, 'accessible-circulation-geometry', 'ISO', 'EN', NULL, 'standard_eb', NULL, 'ISO 21542 ramp gradient maximum slope accessibility built environment requirement', NULL, 'web', 'scoping', NULL, 10, 10, 0, 'none', NULL, NULL, 0, 'session_2026-09-28-research-batch-22-selection', '2026-09-28 19:57', 'First search returned an unreliable WebSearch-tool summary asserting a specific ''1:20 preferred, 1:12 acceptable... used as reference in many countries developing 2026 accessibility codes'' claim with NO corresponding source in the returned link list (a mix of ADA blogs, a ramp calculator, an arxiv paper, USPTO patents) -- treated as an unverified/likely-fabricated tool summary per the same caution as batch 21''s exec 104, NOT used as evidence anywhere. A second, more targeted search found a genuine, if unofficial, primary artefact instead: a 2007 ISO/CD 21542 2nd committee draft, incidentally hosted on a Brazilian government (CNMP) domain -- retrieved by a dedicated follow-up exec.', 0, 'ISO 21542 (Building construction -- Accessibility and usability of the built environment) is the relevant international standard for this parameter; expect the full published text (2011 or 2021 edition) to be commercially paywalled with no free clause-level access, matching every other ISO standard''s typical distribution model -- likely to find only preview/scope pages or secondary paraphrase, not primary clause text.', 'planned', NULL, NULL, '2026-09-28 19:57', 'session_2026-09-28-research-batch-22-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (112, 'accessible-circulation-geometry', 'ISO', 'EN', NULL, 'standard_eb', NULL, 'https://www.cnmp.mp.br/portal/images/Comissoes/DireitosFundamentais/Acessibilidade/Norma_ISO.pdf', NULL, 'web', 'scoping', NULL, 1, 1, 0, 'saturated', NULL, NULL, 0, 'session_2026-09-28-research-batch-22-selection', '2026-09-28 19:58', 'Confirmed: DRAFT PROPOSAL 2nd ISO/CD 21542, dated 2007-11-07 (120pp). Section 8.1 ''Slope and length'', Table 2 gives a full tiered maximum-slope-vs-length table: >=1:20 (5.00%, preferred, up to 10000mm/500mm rise) down through 1:18/1:16/1:14 to 1:12 (8.33%, max 2000mm length/166mm rise), plus a ''step ramp'' sub-category at 1:10 and a ''kerb ramp'' sub-category at 1:8. Table 3 gives RELAXED figures for ''exceptional considerations in adaptation of urban areas or at the entrance of existing buildings'': 1:12 up to 15000mm, 1:10, 1:8, plus a ''threshold ramp'' at 1:8 with no handrail requirement for very short runs. R7 HARM FINDING, verbatim: ''A ramp with a higher gradient than 1:12 means a risk of accident and is heavy to use especially for elderly people and people in wheelchairs. It is not suitable for independent use.'' CAVEAT: this is a 2007 COMMITTEE DRAFT, not the published ISO 21542:2011 or :2021 standard -- neither final edition''s text was independently retrieved (both remain commercially paywalled, no free full-text access found); the draft''s specific figures may not match what was eventually ratified.', 1, 'Follow-up direct retrieval of a document found via exec 111''s second, more targeted search -- a 2007 ISO/CD 21542 draft. Expect it to be a genuine committee working draft (not the final published standard), so any figures found need a draft-vs-final caveat; expect a tiered slope-vs-length table given this parameter''s pattern across every other jurisdiction/standard in the corpus so far.', 'planned', NULL, NULL, '2026-09-28 19:58', 'session_2026-09-28-research-batch-22-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (113, 'accessible-circulation-geometry', 'UN', 'EN', 4, 'grey', 'international', 'United Nations UN-Habitat accessible built environment ramp gradient technical guidance standard', NULL, 'web', 'scoping', NULL, 1, 1, 0, 'none', NULL, NULL, 0, 'session_2026-09-28-research-batch-22-selection', '2026-09-28 20:06', 'No UN-Habitat-authored document with an independent ramp-gradient value found. Surfaced UNICEF ''Accessibility Technical Cards'' (2022), a genuine UN-agency technical compilation with an extensive Section 2.A ''Ramps'' card (p.14-15): a detailed max-rise/max-slope/max-landing-interval schedule (1:20 down to 1:8 for kerb ramps only) and a separate ''Gradients of pathway'' passage (p.7: 1:20 general, max 1:12 for short distances). SCREENED OUT of admission, not zero-yield: every quantified figure in the document is explicitly cited to a THIRD PARTY, not UNICEF''s own research -- the rise/slope table is captioned ''(Source: ISO 2011)'' [the published ISO 21542:2011, distinct from the 2007 CD draft already admitted as REF-01014], Figure 14 ''Measurement of ramp slope'' is ''(Source: ADA 1994)'', and the pathway-gradient figures are ''(Source: UNESCO 1990, Centre for Accessible Environments and RIBA 2004)''. Checked 25+ figure captions across the 44pp document: none is UNICEF-original. Admitting UNICEF as an evidentiary source for these values would cite a tertiary restatement of standards this project should retrieve primarily -- rule 5''s ''second table, same fact'' shape applied to provenance rather than schema. Filed as research_code_leads instead (ISO 21542:2011 published edition; UNESCO 1990) rather than admitted as prose or a source. A well-formed non-admission, not an absence: R14''s honesty standard for a null result applies equally to a found-then-screened-out one. Fetched via curl, extracted via PyMuPDF (44pp, 92797 chars) to a scratch path; not persisted through retrieval_log.fetch() because it will not become an evidence_sources row. UN has no JurisdictionCode enum value (checked schemas/enums.py) -- moot here since nothing is being admitted, but would block a future UN-jurisdiction admission; INT is the correct meta-code for genuinely cross-jurisdictional UN-system material (per REF-00994 precedent), not a missing ''UN'' code.', 0, 'UN-Habitat or another UN body has published a technical guidance document with an independently-sourced quantified ramp-gradient threshold; expecting either a direct hit or a well-formed null, since UN-system agencies more often adopt/reference national or ISO standards rather than author their own dimensional values.', 'planned', NULL, NULL, '2026-09-28 20:06', 'session_2026-09-28-research-batch-22-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (114, 'accessible-circulation-geometry', 'IE', 'EN', 6, 'code', 'national', 'Ireland Building Regulations Technical Guidance Document accessibility ramp gradient maximum slope', NULL, 'web', 'scoping', NULL, 6, 6, 1, 'partial', NULL, NULL, 0, 'session_2026-09-28-research-batch-22-selection', '2026-09-28 20:10', 'Direct hit on the current, official instrument: Technical Guidance Document M (Access and Use) 2022, hosted at assets.gov.ie. Clause 1.1.3.4 ''Ramped access routes'': gradient of 1:20 or steeper = a ramp; preferred maximum 1:20; where site constraints require it, 1:12 permitted if individual flights <=2000mm. Table 1 gives a three-tier graduated schedule (1:20/10m going/500mm rise; 1:15/5m/333mm; 1:12/2m/166mm) with interpolation permitted between -- structurally identical in shape to Norway''s and Ontario''s tiered schedules already admitted this batch. Also found: an older 2000 edition (superseded, not used), and secondary commercial/advocacy pages not used in favour of the primary instrument. Artefact linked via a dedicated follow-up exec (query_text = exact URL), per this batch''s chain-of-custody pattern.', 0, 'Ireland''s Building Regulations (Technical Guidance Document M, Access and Use) will state a specific maximum ramp gradient, most likely in the same 1:12-1:20 band as other bucket-1/2 codes already admitted this batch, since Ireland''s Part M is a mature, EU-aligned statutory instrument.', 'planned', NULL, NULL, '2026-09-28 20:10', 'session_2026-09-28-research-batch-22-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (115, 'accessible-circulation-geometry', 'NZ', 'EN', 6, 'code', 'national', 'New Zealand Building Code accessible route ramp gradient NZS 4121 maximum slope', NULL, 'web', 'scoping', NULL, 9, 9, 1, 'partial', NULL, NULL, 0, 'session_2026-09-28-research-batch-22-selection', '2026-09-28 20:10', 'NZS 4121:2001 is a purchased Standards New Zealand document with no free official copy; found a full-text mirror hosted on archive.org (dn710908.ca.archive.org), NOT an official Standards NZ or govt.nz domain -- same provenance caveat as this batch''s Ontario OBC admission. Content verified internally consistent and self-referencing the real Building Act 1991 s.47A(3). Clause 6.4.2.2 ''Gradient'': maximum gradient of a ramp (other than kerb/step ramp) shall be 1 in 12; commentary C6.4.2.2 recommends 1 in 14 ''wherever achievable''. Definitions clause: a RAMP is any accessible route steeper than 1 in 20 but not steeper than 1 in 12. Also found NZ-govt/BRANZ secondary pages restating the same figures (BRANZ Build magazine article 403''d on fetch; not used as primary). metadata-quality/verification-status downgraded for non-official hosting. Artefact linked via a dedicated follow-up exec.', 0, 'New Zealand''s accessible-route standard (NZS 4121, cited as an Acceptable Solution under the Building Code) will state a maximum ramp gradient in the familiar 1:12-1:20 band; NZS 4121 is a purchased Standards NZ document, so the primary official copy may be paywalled and a workaround may be needed.', 'planned', NULL, NULL, '2026-09-28 20:10', 'session_2026-09-28-research-batch-22-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (116, 'accessible-circulation-geometry', 'IE', 'EN', NULL, NULL, NULL, 'https://assets.gov.ie/100486/12a529ae-7fda-49ab-bc3b-0521fe5be50b.pdf', NULL, 'web', 'scoping', NULL, 1, 1, 1, NULL, NULL, NULL, 0, 'session_2026-09-28-research-batch-22-selection', '2026-09-28 20:10', 'Dedicated artefact-linking exec for REF-01015 (TGD Part M 2022), per chain-of-custody rule.', 0, 'Dedicated follow-up exec whose sole purpose is to bind the already-screened REF-01015 artefact to its exact URL, per this batch''s chain-of-custody pattern; expecting the same document already found and screened in the generic exec.', 'planned', NULL, NULL, '2026-09-28 20:10', 'session_2026-09-28-research-batch-22-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (117, 'accessible-circulation-geometry', 'NZ', 'EN', NULL, NULL, NULL, 'https://dn710908.ca.archive.org/0/items/nzs.4121.2001/nzs.4121.2001.html', NULL, 'web', 'scoping', NULL, 1, 1, 1, NULL, NULL, NULL, 0, 'session_2026-09-28-research-batch-22-selection', '2026-09-28 20:10', 'Dedicated artefact-linking exec for REF-01016 (NZS 4121:2001), per chain-of-custody rule.', 0, 'Dedicated follow-up exec whose sole purpose is to bind the already-screened REF-01016 artefact to its exact URL, per this batch''s chain-of-custody pattern; expecting the same document already found and screened in the generic exec.', 'planned', NULL, NULL, '2026-09-28 20:10', 'session_2026-09-28-research-batch-22-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (118, 'accessible-circulation-geometry', 'FI', 'EN', 6, 'code', 'national', 'Finland building regulations accessibility ramp gradient maximum slope esteettomyys luiska kaltevuus', NULL, 'web', 'scoping', NULL, 9, 9, 1, 'partial', NULL, NULL, 0, 'session_2026-09-28-research-batch-22-selection', '2026-09-28 20:15', 'First hit (edilex.fi/data/rakentamismaaraykset/f1e.pdf, ''F1 Barrier-free Building, Regulations and Guidelines 2005'') is SUPERSEDED -- confirmed via a second targeted search: Government Decree 241/2017 ''on Accessibility of Buildings'' replaced F1 effective 1 Jan 2018, exactly the Norway TEK10/TEK17 trap repeating. Correct current instrument located at Finland''s own official statute portal, Finlex (finlex.fi/en/legislation/2017/241, Ministry of Justice) -- bilingual Finnish/Swedish full text embedded in the page (no separate English legal-translation text on this particular page; Finnish and Swedish are both official enacted languages of Finnish law, so this is not a back-translation concern under R11). Sec. 2(2): ''Luiskan kaltevuus saa olla enintaan viisi prosenttia. Jos korkeusero on enintaan 1 000 millimetria, luiskan kaltevuus saa kuitenkin olla enintaan kahdeksan prosentia'' -- ramp gradient max 5% (1:20) generally, relaxed to max 8% (1:12.5) only where the height difference is <=1000mm, and even then continuous rise before a landing is capped at 500mm. NOTABLE: this is a TIGHTENING relative to the superseded F1 (2005), which allowed 8%/1:12.5 generally (up to 6m continuous) and reserved 5%/1:20 only for landing-free runs -- the current law inverts which gradient is the default and which is the exception. The superseded F1 document was NOT admitted.', 0, 'Finland will have a national statutory accessibility instrument (its RakMK F-series or a successor decree) stating a specific maximum ramp gradient in the familiar 1:12-1:20 band; given the batch''s Norway TEK10/TEK17 near-miss, expecting a live risk that the first hit is a superseded edition rather than the current one.', 'planned', NULL, NULL, '2026-09-28 20:15', 'session_2026-09-28-research-batch-22-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (119, 'accessible-circulation-geometry', 'FI', 'FI', NULL, NULL, NULL, 'https://www.finlex.fi/en/legislation/2017/241', NULL, 'web', 'scoping', NULL, 1, 1, 1, NULL, NULL, NULL, 0, 'session_2026-09-28-research-batch-22-selection', '2026-09-28 20:15', 'Dedicated artefact-linking exec for REF-01017 (Finland Decree 241/2017), per chain-of-custody rule.', 0, 'Dedicated follow-up exec whose sole purpose is to bind the already-screened REF-01017 artefact to its exact URL, per this batch''s chain-of-custody pattern; expecting the same document already found and screened in the generic exec.', 'planned', NULL, NULL, '2026-09-28 20:15', 'session_2026-09-28-research-batch-22-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (120, 'accessible-circulation-geometry', 'FI', 'EN', NULL, NULL, NULL, 'https://www.edilex.fi/data/rakentamismaaraykset/f1e.pdf', NULL, 'web', 'scoping', NULL, 1, 1, 0, NULL, NULL, NULL, 0, 'session_2026-09-28-research-batch-22-selection', '2026-09-28 20:21', 'F1 (2005) is SUPERSEDED by Decree 241/2017 (REF-01017), confirmed via a targeted follow-up search. Not admitted. Logged as a candidate (EXHAUSTED) so a future session does not re-discover and mistakenly admit it as current. || CORRECTED 2026-09-28: Linked a derived page-1 text extraction (PyMuPDF) alongside the persisted PDF, since the PDF itself is undecodable by quote_in_artefacts/add-candidate''s checker -- needed to file a search_candidates row for this superseded document. || CORRECTED 2026-09-28: result artefact(s) added: retrieval-log/session_2026-09-28-research-batch-22-selection/finland_f1_p1.txt', 0, 'Artefact-linking exec for the superseded Finland F1 (2005) regulation, encountered while searching for FI''s current ramp-gradient instrument; expecting to confirm it is superseded and not admit it.', 'planned', NULL, NULL, '2026-09-28 20:22', 'session_2026-09-28-research-batch-22-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (121, 'accessible-circulation-geometry', 'IE', 'EN', NULL, NULL, NULL, 'https://assets.gov.ie/100488/a917ecb9-375d-440e-ab10-e43b6188d955.pdf', NULL, 'web', 'scoping', NULL, 1, 1, 0, NULL, NULL, NULL, 0, 'session_2026-09-28-research-batch-22-selection', '2026-09-28 20:21', 'TGD M (2000 ed.) is SUPERSEDED by the 2022 edition (REF-01015). Not admitted. Logged as a candidate (EXHAUSTED) so a future session does not re-discover and mistakenly admit it as current. || CORRECTED 2026-09-28: Linked a derived page-1 text extraction (PyMuPDF) alongside the persisted PDF, since the PDF itself is undecodable by quote_in_artefacts/add-candidate''s checker -- needed to file a search_candidates row for this superseded document. || CORRECTED 2026-09-28: result artefact(s) added: retrieval-log/session_2026-09-28-research-batch-22-selection/ireland_2000_p1.txt', 0, 'Artefact-linking exec for the superseded Ireland TGD M (2000 ed.), encountered while searching for IE''s current ramp-gradient instrument; expecting to confirm it is superseded by the 2022 edition already admitted as REF-01015.', 'planned', NULL, NULL, '2026-09-28 20:22', 'session_2026-09-28-research-batch-22-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (122, 'accessible-circulation-geometry', NULL, 'EN', 1, 'co1', 'intrinsic', 'occupational therapy wheelchair user lived experience ramp gradient steepness difficulty independent use disability advocacy', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-09-28-research-batch-22-selection', '2026-09-28 20:24', 'R1 pass, this batch''s bucket-1/2 jurisdiction sweep having produced only code/standard (tier 6) admissions so far. Result dominated entirely by COMMERCIAL RAMP-VENDOR content (BraunAbility, RapidRamp, Adapta Ramps, Gilani Engineering, Enable Access -- all businesses selling or installing ramps, not disabled-person-authored or co-produced material) plus a Wikipedia article and a US patent filing. None qualifies as Co-1 (no disabled-person/DPO authorship or co-production visible) or Co-2 (no OT professional-body CPG). Genuinely screened, genuinely null for THIS specific parameter via this query; not evidence that no Co-1 material exists anywhere on ramp gradient (this project''s corpus already holds Co-1 admissions on this exact parameter from batch 9, session_2026-09-16-research-batch-09-ramp-gradient-co1, not re-admitted here to avoid duplication per R9).', 0, 'R1: a lived-experience/DPO-authored source discussing how ramp gradient affects independent wheelchair use should exist and be findable via general web search, given how commonly this topic is discussed in disability advocacy contexts; expecting either a genuine Co-1 hit or a search dominated by commercial ramp-vendor content.', 'planned', NULL, NULL, '2026-09-28 20:24', 'session_2026-09-28-research-batch-22-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (123, 'accessible-circulation-geometry', NULL, 'EN', 2, 'co2', 'intrinsic', '"Royal College of Occupational Therapists" OR "College of Occupational Therapists" ramp gradient wheelchair housing adaptation guidance', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-09-28-research-batch-22-selection', '2026-09-28 20:24', 'Found RCOT''s real, current publication ''Adaptations without delay'' (referenced via a trade-press summary, THIIS Magazine) -- but it addresses adaptation PROCESS/delay reduction, not ramp technical specifications; not on-point for this parameter. Remaining hits are OT-sector secondary/training content (Housing LIN, Foundations, The OT Practice, Moddy, Enable Access) restating the same 1:12/1:15/1:20 figures already independently admitted this batch from primary code sources, with no distinct OT-body-sourced figure of their own and no clause-level citation to a named CPG document. No Co-2 admission made: nothing found rises above a secondary restatement of code figures already in the corpus. Genuinely screened, genuinely null for a distinct Co-2 anchor on THIS parameter via this query.', 0, 'R1/Co-2: a national OT professional body (RCOT is the obvious English-language candidate, being both prolific and heavily indexed) will have published a clinical practice guideline or technical resource stating or endorsing a specific ramp gradient for housing adaptations; expecting either a direct CPG hit or, if RCOT''s own site is not well-indexed for this specific figure, a secondary OT-sector summary of RCOT guidance.', 'planned', NULL, NULL, '2026-09-28 20:24', 'session_2026-09-28-research-batch-22-selection');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (124, 'accessible-circulation-geometry', 'UN', 'EN', NULL, NULL, NULL, 'https://shelterprojects.org/other/siteplanning/site-planning-references/UNICEF%20Accessibility%20Technical%20Cards%20(2022).pdf', NULL, 'web', 'scoping', NULL, 1, 1, 0, NULL, NULL, NULL, 0, 'session_2026-09-28-research-batch-22-selection', '2026-09-28 20:26', 'Re-locates and persists the exact document already fully screened in exec 113: every quantified ramp-gradient figure in it traces to a third party (ISO 2011, ADA 1994, UNESCO 1990, Centre for Accessible Environments/RIBA 2004), not to UNICEF''s own research. See exec 113 for the full screening rationale. This exec exists only to give the candidate row (below) a linkable artefact. || CORRECTED 2026-09-28: Linked a derived page-1 text extraction (PyMuPDF) alongside the persisted PDF, since the PDF itself is undecodable by quote_in_artefacts/add-candidate''s checker -- needed to file a search_candidates row for this screened-not-admitted document. || CORRECTED 2026-09-28: result artefact(s) added: retrieval-log/session_2026-09-28-research-batch-22-selection/unicef_p1.txt', 0, 'Artefact-linking exec for the UNICEF Accessibility Technical Cards (2022), already screened and dispositioned NOT-ADMITTED in exec 113 (this batch''s UN pass); the original fetch''s exact URL was lost across a context-window compaction mid-session, so this re-locates and properly persists the identical document (confirmed by matching byte count, 2453131) via its canonical host.', 'planned', NULL, NULL, '2026-09-28 20:26', 'session_2026-09-28-research-batch-22-selection');
