INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id", "surfaced_in", "surfaced_quote", "updated_at", "updated_by_session") VALUES (133, 120, 'accessible-circulation-geometry', NULL, 'OUT-OF-SCOPE', 'F1 The Finnish Building Regulations -- Barrier-free Building, Regulations and Guidelines 2005 (Ministry of the Environment Decree, adopted 1 Oct 2004)', 'https://www.edilex.fi/data/rakentamismaaraykset/f1e.pdf', 'RESOLVED', 6, 0, 'SUPERSEDED: replaced by Government Decree 241/2017 ''on Accessibility of Buildings'', in force since 1 Jan 2018 (admitted this batch as REF-01017). F1''s own ramp-gradient figures (8%/1:12.5 general, 5%/1:20 landing-free) are the INVERSE of the current decree''s default/exception structure -- retained here only as a negative record so a future session does not re-discover this PDF and mistakenly admit it as current law.', ' || RESOLVED 2026-09-28 by session_2026-09-28-research-batch-22-selection: R15, re-described from the source: CORRECTION (independent adversarial pass, batch 22): EXHAUSTED was the wrong disposition -- the 2026-09-25 owner ruling reserves EXHAUSTED for no-route (unreachable) items only (''Keep EXHAUSTED for no-route items only. A transient barrier stays PENDING-VERIFICATION with a note.''). This document was fully retrieved and read (status 200, persisted); it is excluded because it is a superseded regulation, not because it is unreachable. OUT-OF-SCOPE is the closer fit among the CHECK-permitted values.', 'session_2026-09-28-research-batch-22-selection', '2026-09-28 20:23', NULL, 'retrieval-log/session_2026-09-28-research-batch-22-selection/finland_f1_p1.txt', 'F1 THE FINNISH BUILDING REGULATIONS', '2026-09-28 20:59', 'session_2026-09-28-research-batch-22-selection');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id", "surfaced_in", "surfaced_quote", "updated_at", "updated_by_session") VALUES (134, 121, 'accessible-circulation-geometry', NULL, 'OUT-OF-SCOPE', 'Building Regulations 2000, Technical Guidance Document M -- Access for People with Disabilities', 'https://assets.gov.ie/100488/a917ecb9-375d-440e-ab10-e43b6188d955.pdf', 'RESOLVED', 6, 0, 'SUPERSEDED: replaced by the 2022 edition of TGD M ''Access and Use'' (admitted this batch as REF-01015). Retained as a negative record so a future session does not re-discover this PDF and mistakenly admit it as current law.', ' || RESOLVED 2026-09-28 by session_2026-09-28-research-batch-22-selection: R15, re-described from the source: CORRECTION (independent adversarial pass, batch 22): this candidate''s original why_not_admitted said the 2000 edition was ''replaced by the 2022 edition ... admitted this batch as REF-01015'' -- that attribution is now known WRONG. REF-01015 was itself discovered (same adversarial pass) to be a mislabeled copy of the RETIRED 2010 edition, not the 2022 edition. The genuine 2022 edition of TGD M is now separately admitted as REF-01018. This candidate''s own disposition (EXHAUSTED, a superseded 2000-edition PDF, correctly identified as such) is unaffected by that correction and stands. || RESOLVED 2026-09-28 by session_2026-09-28-research-batch-22-selection: R15, re-described from the source: CORRECTION (independent adversarial pass, batch 22): EXHAUSTED was the wrong disposition, for the same reason as candidate 133 -- this document was fully retrieved and read; it is excluded because it is a superseded edition, not because it is unreachable. OUT-OF-SCOPE is the closer fit. (This is IN ADDITION to this candidate''s earlier REF-01015 attribution correction, above.)', 'session_2026-09-28-research-batch-22-selection', '2026-09-28 20:23', NULL, 'retrieval-log/session_2026-09-28-research-batch-22-selection/ireland_2000_p1.txt', 'Building Regulations 2000', '2026-09-28 20:59', 'session_2026-09-28-research-batch-22-selection');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id", "surfaced_in", "surfaced_quote", "updated_at", "updated_by_session") VALUES (135, 124, 'accessible-circulation-geometry', NULL, 'OUT-OF-SCOPE', 'UNICEF Accessibility Technical Cards (2022) -- Accessible Components for the Built Environment: Technical Guidelines embracing Universal Design', 'https://shelterprojects.org/other/siteplanning/site-planning-references/UNICEF%20Accessibility%20Technical%20Cards%20(2022).pdf', 'RESOLVED', 4, 0, 'Every quantified ramp-gradient figure in this 44pp document is explicitly captioned to a THIRD PARTY, not UNICEF''s own research: the detailed rise/slope/landing table is ''(Source: ISO 2011)'', Figure 14 ''Measurement of ramp slope'' is ''(Source: ADA 1994)'', and the pathway-gradient figures are ''(Source: UNESCO 1990, Centre for Accessible Environments and RIBA 2004)''. Checked 25+ figure captions; none is UNICEF-original. Admitting it as a distinct evidentiary source would cite a tertiary restatement of standards already represented (or lead-filed as GAP-056/research_code_leads 94-95) elsewhere in this corpus -- the rule-5 ''second table, same fact'' shape applied to provenance. Full screening in search_executions exec_id 113.', NULL, 'session_2026-09-28-research-batch-22-selection', '2026-09-28 20:26', NULL, 'retrieval-log/session_2026-09-28-research-batch-22-selection/unicef_p1.txt', 'Accessible Components for the Built Environment', '2026-09-28 20:26', 'session_2026-09-28-research-batch-22-selection');
