INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (74, 'REF-01012', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'NO', NULL, 'numerical', '1:15', 'rise:run ratio (general maximum; relaxed to 1:12 for runs under 3.0m -- see comparator note)', 'Rampe skal ha jevnt og sklisikkert dekke og stigning maksimum 1:15. For strekninger under 3,0 m kan stigningen være maksimum 1:12.', 'TEK17 § 12-16(2)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '12-16', NULL, '2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'Tiered by run length: general max 1:15, relaxed to 1:12 only for runs under 3.0m -- same tiering SHAPE as REF-01010 (Uganda, single 1:12 threshold) and the Spain/France leads from batch 21 (10/8/6% and 5/8/10/12% multi-tier), but Norway''s own tiering is simpler (two tiers, not three+). Clause (1) states the minimum-width requirement (0.9m) is explicitly grounded in wheelchair use (''Kravet til minimumsbredde er gitt med bakgrunn i bruk av rullestol''), and (2) also requires a 1.5m rest landing per 1.0m of height risen -- not filed as a separate extraction (this parameter''s row is gradient only; landing/width belong to other parameters if this project tracks them separately).', '2026-09-28 19:49', 'session_2026-09-28-research-batch-22-selection', '2026-09-28 19:49', 'session_2026-09-28-research-batch-22-selection', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (75, 'REF-01013', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'CA', NULL, 'numerical', '1:12', 'rise:run ratio', 'Ramps located in a barrier-free path of travel shall, (a) have a minimum width of 900 mm between handrails, (b) have a maximum gradient of 1 in 12', 'OBC 3.8.3.4(1)(b)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '3.8.3.4', NULL, '1', 'b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'Retrieved via a NON-GOVERNMENTAL mirror (buildingcode.online), which self-discloses ''not an official copy... maintained by the Government of Ontario'' -- verification_status is UNVERIFIED accordingly, not COMPLETE-STATUTORY. A second, independent web search corroborated the gradient figure specifically against the CURRENT (2024, O.Reg 163/24) edition, noting the minimum width changed from 900mm (shown here, 2012/2017 text) to 1000mm in 2024 -- the gradient itself (1:12) is unchanged across editions per that corroboration, but width is out of this parameter''s scope and not re-extracted. DISTINCT FROM OBC 3.4.6.7 (''Ramp Slope''), a GENERAL (non-barrier-free) ramp provision in the same code with occupancy-dependent slopes (1:6 mercantile/industrial, 1:8 other, 1:10 assembly/care/residential/exterior) -- that clause is NOT this parameter; a ramp built to 3.4.6.7 alone would not necessarily satisfy 3.8.3.4''s accessibility requirement.', '2026-09-28 19:55', 'session_2026-09-28-research-batch-22-selection', '2026-09-28 19:55', 'session_2026-09-28-research-batch-22-selection', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (76, 'REF-01014', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'ISO', NULL, 'numerical', '1:20', 'rise:run ratio (preferred/least-steep tier; the draft''s own words: ''The slope shall be the lowest possible and not exceed the maximums set out in Table 2'')', 'The slope shall be the lowest possible and not exceed the maximums set out in Table 2 and 3.', 'Table 2 — Maximum slope and length of ramps, clause 8.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '8.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'DRAFT, NOT THE PUBLISHED STANDARD: this is the 2007-11-07 ISO/CD 21542 2nd committee draft (ISO/TC 59/SC 16/WG 1, secretariat AENOR); the document''s own cover states ''This document is not an ISO International Standard... may not be referred to as an International Standard.'' Neither the 2011 nor the 2021 published edition was independently retrieved (both commercially paywalled). Table 2''s FULL tiered slope-vs-length schedule (verbatim figures, going/rise in mm): >=1:20 (5.00%) up to 10000mm/500mm; 1:18 (5.56%) to 8000mm/444mm; 1:16 (6.25%) to 6000mm/357mm; 1:14 (7.14%) to 4000mm/286mm; 1:12 (8.33%) to 2000mm/166mm; a ''step ramp'' sub-category at 1:10 (10.00%) to 1900mm/190mm; a ''kerb ramp'' sub-category at 1:8 (12.50%) to 1520mm/190mm. Table 3 (retrofit/existing-building exception) relaxes this: 1:12 to 15000mm/1250mm, 1:10 to 10000mm/1000mm, 1:8 to 3000mm/375mm, plus a ''threshold ramp'' at 1:8 with NO handrail requirement for very short runs. This extraction files only the top-tier (preferred, least-steep) figure; the full schedule is preserved verbatim in this note rather than as further rows, matching this project''s practice of not exhaustively re-extracting every cell of a multi-tier table already summarised in one row''s notes (cf. REF-00992''s UK table, extractions 25-26). [VERBATIM-EXEMPT: Source is a binary PDF (retrieval-log/session_2026-09-28-research-batch-22-selection/64b22ee89a4f5762.pdf, sha256 64b22ee89a4f57626263d66666cd87402e7452cada780ec4011f706867b79767, 2693415 bytes) -- content streams do not decode as text for quote_in_artefacts. Text extracted via PyMuPDF in this session (page 29-30, clause 8.1 ''Slope and length'').]', '2026-09-28 19:59', 'session_2026-09-28-research-batch-22-selection', '2026-09-28 19:59', 'session_2026-09-28-research-batch-22-selection', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (77, 'REF-01014', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'ISO', NULL, 'qualitative', 'a ramp with a higher gradient than 1:12 means a risk of accident and is heavy to use, especially for elderly people and people in wheelchairs, and is not suitable for independent use', NULL, 'A ramp with a higher gradient than 1:12 means a risk of accident and is heavy to use especially for elderly people and people in wheelchairs. It is not suitable for independent use. Ramps with a higher gradient than 1:12 should therefore only be used in existing environments under special circumstances decided at a National Level.', 'NOTE following Table 3, clause 8.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '8.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'R7 HARM/LIMITATION FINDING. Same draft-vs-published-standard caveat as extraction_id=76. This note explains the RATIONALE for the 1:12 threshold that recurs across nearly every jurisdiction/standard in this corpus (Uganda, Ontario, and the UK/ADA-family sources already admitted) -- the drafting committee''s own reasoning for why 1:12 is treated as a ceiling rather than a target, and why anything steeper is explicitly scoped to ''existing environments under special circumstances decided at a National Level'' rather than new construction. Directly corroborates and explains REF-01010/1012/1013''s own single-threshold framing. [VERBATIM-EXEMPT: Same persisted PDF as extraction_id=76 (retrieval-log/session_2026-09-28-research-batch-22-selection/64b22ee89a4f5762.pdf); see that row for the verbatim-exemption warrant.]', '2026-09-28 19:59', 'session_2026-09-28-research-batch-22-selection', '2026-09-28 19:59', 'session_2026-09-28-research-batch-22-selection', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (78, 'REF-01015', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'IE', NULL, 'numerical', '1:20', 'rise:run ratio (preferred maximum; relaxed to 1:12 where site constraints require it, for flights not exceeding 2000mm going)', 'For the purpose of this guidance, a gradient of 1:20 or steeper is considered to be a ramp. Ramped access routes should be designed to have the shallowest gradient practical. The preferred maximum gradient is 1:20 but where site specific constraints require it, ramps not steeper than 1:12 may be provided if individual flights are not longer than 2000 mm.', 'TGD M (2022) clause 1.1.3.4, Table 1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '1.1.3.4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'Table 1 gives a full three-tier graduated schedule keyed on flight going: going <=10m -> max gradient 1:20, max rise 500mm; going <=5m -> max gradient 1:15, max rise 333mm; going <=2m -> max gradient 1:12, max rise 166mm; interpolation permitted between tiers (Diagram 3). Same graduated-by-run-length SHAPE as REF-01012 (Norway, two tiers) and REF-01010 (Uganda, single threshold), corroborating the recurring pattern that steeper gradients are only tolerated over shorter runs across this corpus''s jurisdictions. Distinguish from Ireland''s separate general ''gently sloped'' classification (1:50 to 1:20, not treated as a ramp at all, no handrail/landing requirements). [VERBATIM-EXEMPT: PDF content stream (retrieval-log/session_2026-09-28-research-batch-22-selection/5623203cc3eb3c88.pdf) not decodable by quote_in_artefacts; text independently extracted via PyMuPDF and matches the persisted artefact byte-for-byte at sha256 5623203c... (see manifest.jsonl). Same limitation class as REF-01014 (ISO draft) this batch.]', '2026-09-28 20:12', 'session_2026-09-28-research-batch-22-selection', '2026-09-28 20:12', 'session_2026-09-28-research-batch-22-selection', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (79, 'REF-01016', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'NZ', NULL, 'numerical', '1:12', 'rise:run ratio (maximum; 1:14 recommended as achievable-preferred in non-binding commentary)', '6.4.2.2 Gradient The maximum gradient of a ramp other than a kerb or step ramp shall be 1 in 12, figure 11. C6.4.2.2 Every effort should be made to construct a ramp as flat as possible. A maximum gradient of 1 in 14 should be used wherever it is achievable.', 'NZS 4121:2001 clause 6.4.2.2, commentary C6.4.2.2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '6.4.2.2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'NZS uses the same normative-clause + non-binding-commentary structure as several other standards in this corpus. The commentary''s 1:14 is explicitly NOT a requirement (''should be used wherever achievable''), distinct from the binding 1:12 ceiling -- captured in --claimed-unit rather than as a separate extraction, to avoid implying two independently-sourced values. Standard''s own definitions clause additionally frames the RAMP/route boundary identically to Ontario''s OBC and this batch''s ISO draft: an accessible route steeper than 1:20 but not steeper than 1:12 is classified a ramp; anything within 1:20-and-shallower is a sloped route, not a ramp, and carries different requirements. Third jurisdiction this batch to draw that same 1:20/1:12 boundary independently (also Ireland REF-01015, ISO REF-01014).', '2026-09-28 20:12', 'session_2026-09-28-research-batch-22-selection', '2026-09-28 20:12', 'session_2026-09-28-research-batch-22-selection', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (80, 'REF-01017', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'FI', NULL, 'numerical', 'viisi prosenttia', 'Finnish spelled-out cardinal, = 5 percent = 1:20 (general maximum; relaxed to ''kahdeksan prosenttia'' = 8 percent = 1:12.5 where the total height difference is <=1000mm and continuous rise before a landing <=500mm). Digit-equivalents are an editorial gloss, not verbatim -- see notes and GAP filed this batch on _require_verbatim''s digit-check.', 'Luiskan kaltevuus saa olla enintään viisi prosenttia. Jos korkeusero on enintään 1 000 millimetriä, luiskan kaltevuus saa kuitenkin olla enintään kahdeksan prosenttia.', 'Valtioneuvoston asetus 241/2017, 2 S, 2 mom.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '2', NULL, '2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'claimed_value is left in the source''s own spelled-out form (''viisi prosenttia'') rather than a digit ''5%'', because scripts/db.py''s _require_verbatim digit-check (widened 2026- for CJK numerals) has no path for Latin-script spelled-out cardinals -- Finnish statutory prose writes every number as a word, never a digit, so no digit-bearing claimed_value can pass the check, and --verbatim-exempt is itself refused whenever the text DOES verify (it did, confirmed via quote_in_artefacts). This is a genuine, reproducible tooling gap, not a corner cut on this row; filed as a GAP this batch rather than hand-patched (rule 10: tooling ships apart from research rows). Numeric equivalents (5%=1:20 general; 8%=1:12.5 narrow exception) are given in --claimed-unit as an editorial gloss for readability, clearly marked as not verbatim. Finnish and Swedish are both official enacted languages of this statute; using the Finnish text is not a back-translation under R11. This is the strictest general ramp ceiling (1:20) of any jurisdiction admitted this batch -- the superseded 2005 F1 regulation (not admitted) permitted 8%/1:12.5 generally, so a reader citing the old text would overstate current permissiveness.', '2026-09-28 20:17', 'session_2026-09-28-research-batch-22-selection', '2026-09-28 20:17', 'session_2026-09-28-research-batch-22-selection', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (81, 'REF-01018', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'IE', NULL, 'numerical', '1:20', 'rise:run ratio (preferred maximum; relaxed to 1:12 where site constraints require it, for flights not exceeding 2000mm going)', 'For the purpose of this guidance, a gradient of 1:20 or steeper is considered to be a ramp. Ramped access routes should be designed to have the shallowest gradient practical. The preferred maximum gradient is 1:20 but where site specific constraints require it, ramps not steeper than 1:12 may be provided if individual flights are not longer than 2000 mm.', 'TGD M 2022, clause 1.1.3.4, Table 2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '1.1.3.4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'CORRECTS extraction_id=78 on REF-01015: an independent adversarial pass found REF-01015''s PDF is actually the 2010 edition of TGD M (mislabeled 2022 at admission -- ISBN 978-1-4064-2317-4, ''(c) Government of Ireland 2010'', PDF metadata creationDate 20101110), which itself self-declares (via the genuine 2022 edition''s own transitional text, checked here) that it ceased to have legal effect on 1 January 2024. This extraction is against the byte-verified GENUINE 2022 edition (title page: ''Building Regulations Technical Guidance Document M 2022 Access and Use'', ''Prepared by the Department of Housing, Local Government and Heritage'', 180pp, galway.ie mirror of the official document). The clause 1.1.3.4 text and Table (numbered Table 2 here vs Table 1 in the 2010 text) carry the identical substantive rule -- Irish law on this point was continuous from 2010 through the 2022 edition''s own effective date -- but REF-01018, not REF-01015, is the correctly-identified CURRENT instrument and should be cited as such. [VERBATIM-EXEMPT: PDF content stream (retrieval-log/session_2026-09-28-research-batch-22-selection/e6042db0542ad404.pdf) not decodable by quote_in_artefacts; text independently extracted via PyMuPDF and matches the persisted artefact byte-for-byte at sha256 e6042db0... (see manifest.jsonl). Same limitation class as REF-01014/01015 this batch.]', '2026-09-28 20:56', 'session_2026-09-28-research-batch-22-selection', '2026-09-28 20:56', 'session_2026-09-28-research-batch-22-selection', 'claim', '<=');